[TFMPageType('OrderList', "Locking Mechanism")]
class TFMDataSourceBlockLockOrderList extends TFMDataSourceBlock
{
    NoYes           useOrderLocking;
    TFMBackendId	backendId;
    TFMLockingLevel lockingLevel;

}

Method.Source:
public void new()
{
    useOrderLocking = true;
    lockingLevel = TFMLockingLevel::Both;
}

[TFMParameter(TFMLockingLevel::Both,"@TFM:UseOrderLocking")]
public TFMLockingLevelEDT parmLockingLevel(TFMLockingLevelEDT _lockingLevel = lockingLevel)
{
    lockingLevel = _lockingLevel;
    return lockingLevel;
}

public TFMPromptForUnit parmUseOrderLocking(TFMPromptForUnit _useOrderLocking = useOrderLocking)
{
    useOrderLocking = _useOrderLocking;
    return useOrderLocking;
}

public Map AddFields(Common _common)
{
    Map				ret			= super(_common);
    if (!backendId)
    {
        backendId= TFMHelper::generateBackendId(_common,ds.OrderType);
    }
    useOrderLocking = lockingLevel != TFMLockingLevel::Never;
    ret.insert(TFMConstants::Status(), useOrderLocking && TFMLockedOrders::isOrderLocked(backendid,deviceId, lockingLevel) ? TFMConstants::locked() : TFMConstants::Unlocked());
    return ret;
}
